                    a38 = fma(qj, r0_3_2_0, a38);
                    a39 = fma(qj, r0_3_1_1, a39);
                    a40 = fma(qj, r0_3_0_2, a40);
                    a41 = fma(qj, r0_2_3_0, a41);
                    a42 = fma(qj, r0_2_2_1, a42);
                    a43 = fma(qj, r0_2_1_2, a43);
                    a44 = fma(qj, r0_2_0_3, a44);
                    a45 = fma(qj, r0_1_4_0, a45);
                    a46 = fma(qj, r0_1_3_1, a46);
                    a47 = fma(qj, r0_1_2_2, a47);
                    a48 = fma(qj, r0_1_1_3, a48);
                    a49 = fma(qj, r0_1_0_4, a49);
                    a50 = fma(qj, r0_0_5_0, a50);
                    a51 = fma(qj, r0_0_4_1, a51);
                    a52 = fma(qj, r0_0_3_2, a52);
                    a53 = fma(qj, r0_0_2_3, a53);
                    a54 = fma(qj, r0_0_1_4, a54);
                    a55 = fma(qj, r0_0_0_5, a55);
                }
            }
            if (want_v) {
                // the warp's share, a fixed shuffle tree
                for (int o = LINUS_WARP_SIZE / 2; o > 0; o >>= 1) v += linus_shfl_down(v, o);
                if (lane == 0) sw[warp * 32 + j] = v;
            }
        }
        __syncthreads();
        if (want_v && tid < ng) {
            // the block's share of the potential at point g0 + tid, warps in order
            double s = 0.0;
            for (int w = 0; w < (128 / LINUS_WARP_SIZE); ++w) s += sw[w * 32 + tid];
            vpart[(vblock0 + blockIdx.x) * npts + g0 + tid] = s;
        }
    }
    if (act && want_m) {
        double *ap = acc + 56 * ((long long)blockIdx.y * nprim + ip);
